insert into public.trips (slug,type,title,destination,days,hours,duration_label,price_usd,min_group,pickup,group_size,image,image_alt,gallery,summary,highlights,itinerary,included,excluded,faqs,featured,sort_order) values
('3-day-maasai-mara-classic','safari','3-Day Maasai Mara Classic','maasai-mara',3,null,'3 days / 2 nights',650,1,'Nairobi hotel or JKIA','2 – 7 guests','tours/3-day-maasai-mara-classic/1-cover.jpg','Male lion resting on a termite mound in the Maasai Mara','[{"src":"tours/3-day-maasai-mara-classic/1-cover.jpg","alt":"Male lion resting on a termite mound in the Maasai Mara"},{"src":"tours/3-day-maasai-mara-classic/2.jpg","alt":"Pop-up roof safari vehicle watching a cheetah on the Mara plains"},{"src":"tours/3-day-maasai-mara-classic/3.jpg","alt":"Hot-air balloons drifting over the Mara at sunrise"},{"src":"tours/3-day-maasai-mara-classic/4.jpg","alt":"Maasai warriors performing the traditional jumping dance"}]'::jsonb,'Our most-loved short safari. Two full days of game drives in the Maasai Mara — Kenya''s most famous reserve — chasing lions, cheetahs, elephants and, in season, the Great Migration.',array['Big Five game drives','Maasai village visit','Optional balloon safari'],'[{"day":"Day 1","title":"Nairobi → Maasai Mara","description":"Early pick-up and scenic drive via the Great Rift Valley viewpoint. Arrive for lunch at camp, then an afternoon game drive until sunset."},{"day":"Day 2","title":"Full day in the Mara","description":"A full day exploring the reserve with a picnic lunch near the Mara River — prime territory for big cats and river crossings (Jul–Oct)."},{"day":"Day 3","title":"Morning drive → Nairobi","description":"Sunrise game drive, breakfast, then optional Maasai village visit before returning to Nairobi by late afternoon."}]'::jsonb,s_inc,s_exc,s_faq,true,0),
('4-day-amboseli-tsavo-explorer','safari','4-Day Amboseli & Tsavo Explorer','amboseli',4,null,'4 days / 3 nights',890,1,'Nairobi hotel or JKIA','2 – 7 guests','tours/4-day-amboseli-tsavo-explorer/1-cover.jpg','Elephant herd walking beneath snow-capped Mount Kilimanjaro in Amboseli','[{"src":"tours/4-day-amboseli-tsavo-explorer/1-cover.jpg","alt":"Elephant herd walking beneath snow-capped Mount Kilimanjaro in Amboseli"},{"src":"tours/4-day-amboseli-tsavo-explorer/2.jpg","alt":"Red-dusted Tsavo elephants drinking at a waterhole"},{"src":"tours/4-day-amboseli-tsavo-explorer/3.jpg","alt":"Crystal-clear Mzima Springs pool with a hippo in Tsavo West"},{"src":"tours/4-day-amboseli-tsavo-explorer/4.jpg","alt":"Safari lodge terrace overlooking the Amboseli plains at dusk"}]'::jsonb,'Elephants beneath Kilimanjaro, then the wild red earth of Tsavo West and East. A perfect safari for photographers and elephant lovers.',array['Kilimanjaro views','Mzima Springs hippos','Red elephants of Tsavo'],'[{"day":"Day 1","title":"Nairobi → Amboseli","description":"Drive south to Amboseli for lunch and an afternoon game drive with Kilimanjaro views."},{"day":"Day 2","title":"Amboseli → Tsavo West","description":"Morning drive in Amboseli, then on to Tsavo West. Visit Mzima Springs to see hippos underwater."},{"day":"Day 3","title":"Tsavo East","description":"Explore Tsavo East''s open plains, Aruba Dam and Lugard Falls, famous for its dust-red elephants."},{"day":"Day 4","title":"Tsavo → Nairobi or Mombasa","description":"Final sunrise drive, then transfer to Nairobi or extend to the Mombasa coast."}]'::jsonb,s_inc,s_exc,s_faq,true,1),
('5-day-mara-lake-nakuru-combo','safari','5-Day Mara & Lake Nakuru Combo','maasai-mara',5,null,'5 days / 4 nights',1150,1,'Nairobi hotel or JKIA','2 – 7 guests','tours/5-day-mara-lake-nakuru-combo/1-cover.jpg','Wildebeest leaping into the Mara River during the Great Migration','[{"src":"tours/5-day-mara-lake-nakuru-combo/1-cover.jpg","alt":"Wildebeest leaping into the Mara River during the Great Migration"},{"src":"tours/5-day-mara-lake-nakuru-combo/2.jpg","alt":"Pink flamingos lining the shore of Lake Nakuru"},{"src":"tours/5-day-mara-lake-nakuru-combo/3.jpg","alt":"White rhino mother and calf grazing at Lake Nakuru"},{"src":"tours/5-day-mara-lake-nakuru-combo/4.jpg","alt":"Leopard resting along the branch of an acacia tree"}]'::jsonb,'The best of the Rift Valley and the Mara: rhinos and flamingos at Lake Nakuru, then three nights of world-class game viewing in the Maasai Mara.',array['Rhino sanctuary','Flamingo shores','3 nights in the Mara'],'[{"day":"Day 1","title":"Nairobi → Lake Nakuru","description":"Drive through the Rift Valley to Lake Nakuru for an afternoon game drive looking for rhinos and tree-climbing lions."},{"day":"Day 2","title":"Nakuru → Maasai Mara","description":"Morning in Nakuru, then continue to the Mara for an evening game drive."},{"day":"Day 3","title":"Full day Maasai Mara","description":"Full-day game drive with picnic lunch along the Mara River."},{"day":"Day 4","title":"Maasai Mara","description":"Morning and afternoon drives, with an optional Maasai cultural visit in between."},{"day":"Day 5","title":"Mara → Nairobi","description":"Sunrise drive and breakfast before returning to Nairobi."}]'::jsonb,s_inc,s_exc,s_faq,true,2),
('2-day-maasai-mara-express','safari','2-Day Maasai Mara Express','maasai-mara',2,null,'2 days / 1 night',420,1,'Nairobi hotel or JKIA','2 – 7 guests','tours/2-day-maasai-mara-express/1-cover.jpg','Lioness walking through tall golden grass in the Maasai Mara','[{"src":"tours/2-day-maasai-mara-express/1-cover.jpg","alt":"Lioness walking through tall golden grass in the Maasai Mara"},{"src":"tours/2-day-maasai-mara-express/2.jpg","alt":"Safari tented camp glowing with lanterns at dusk"},{"src":"tours/2-day-maasai-mara-express/3.jpg","alt":"Topi and zebras grazing on the open Mara plains"}]'::jsonb,'Short on time? See the Mara in a quick, action-packed overnight safari.',array['Ideal for short stays','Sunset game drive','Tented camp'],'[{"day":"Day 1","title":"Nairobi → Maasai Mara","description":"Early departure, lunch at camp and a long afternoon game drive."},{"day":"Day 2","title":"Mara → Nairobi","description":"Sunrise drive, breakfast, return to Nairobi by evening."}]'::jsonb,s_inc,s_exc,s_faq,false,3),
('6-day-samburu-ol-pejeta-nakuru','safari','6-Day Samburu, Ol Pejeta & Nakuru','samburu',6,null,'6 days / 5 nights',1650,1,'Nairobi hotel or JKIA','2 – 7 guests','tours/6-day-samburu-ol-pejeta-nakuru/1-cover.jpg','Reticulated giraffes among doum palms in Samburu','[{"src":"tours/6-day-samburu-ol-pejeta-nakuru/1-cover.jpg","alt":"Reticulated giraffes among doum palms in Samburu"},{"src":"tours/6-day-samburu-ol-pejeta-nakuru/2.jpg","alt":"Grevy''s zebras drinking at the Ewaso Nyiro River"},{"src":"tours/6-day-samburu-ol-pejeta-nakuru/3.jpg","alt":"Rhinos grazing at Ol Pejeta with Mount Kenya behind"}]'::jsonb,'Head north for rare species, rhinos at Ol Pejeta and the flamingo shores of Nakuru.',array['Samburu Special Five','Northern white rhinos','Equator crossing'],'[{"day":"Day 1","title":"Nairobi → Samburu","description":"Drive north past Mt Kenya to Samburu."},{"day":"Day 2","title":"Samburu","description":"Full day searching for Grevy''s zebra, gerenuk and Beisa oryx."},{"day":"Day 3","title":"Samburu → Ol Pejeta","description":"Transfer to Ol Pejeta Conservancy."},{"day":"Day 4","title":"Ol Pejeta","description":"Rhino tracking and the Sweetwaters chimpanzee sanctuary."},{"day":"Day 5","title":"Ol Pejeta → Lake Nakuru","description":"Via Thomson''s Falls to Lake Nakuru."},{"day":"Day 6","title":"Nakuru → Nairobi","description":"Morning game drive, return to Nairobi."}]'::jsonb,s_inc,s_exc,s_faq,false,4),
('7-day-big-five-grand-kenya','safari','7-Day Big Five Grand Kenya','maasai-mara',7,null,'7 days / 6 nights',2150,1,'Nairobi hotel or JKIA','2 – 7 guests','tours/7-day-big-five-grand-kenya/1-cover.jpg','Leopard resting on a branch','[{"src":"tours/7-day-big-five-grand-kenya/1-cover.jpg","alt":"Leopard resting on a branch"},{"src":"tours/7-day-big-five-grand-kenya/2.jpg","alt":"Cape buffalo herd in the early-morning mist"},{"src":"tours/7-day-big-five-grand-kenya/3.jpg","alt":"Hippos surfacing in Lake Naivasha at sunrise"},{"src":"tours/7-day-big-five-grand-kenya/4.jpg","alt":"Lion pride on a rocky outcrop at sunset"}]'::jsonb,'The ultimate Kenya circuit: Amboseli, Naivasha, Nakuru and the Maasai Mara in one week.',array['4 parks in 7 days','Naivasha boat ride','Best Big Five odds'],'[{"day":"Day 1–2","title":"Amboseli","description":"Elephants and Kilimanjaro views."},{"day":"Day 3","title":"Lake Naivasha","description":"Boat ride and Crescent Island walking safari."},{"day":"Day 4","title":"Lake Nakuru","description":"Rhinos and flamingos."},{"day":"Day 5–6","title":"Maasai Mara","description":"Two full days in Kenya''s finest reserve."},{"day":"Day 7","title":"Return to Nairobi","description":"Morning drive and transfer back."}]'::jsonb,s_inc,s_exc,s_faq,false,5),
('nairobi-national-park-day-trip','day-trip','Nairobi National Park Game Drive','nairobi',1,5,'Half day · 5 hrs',95,1,'Nairobi CBD, Westlands or JKIA','1 – 7 guests','tours/nairobi-national-park-day-trip/1-cover.jpg','Giraffe in Nairobi National Park with the city skyline behind','[{"src":"tours/nairobi-national-park-day-trip/1-cover.jpg","alt":"Giraffe in Nairobi National Park with the city skyline behind"},{"src":"tours/nairobi-national-park-day-trip/2.jpg","alt":"Giraffes and zebras grazing in the park"},{"src":"tours/nairobi-national-park-day-trip/3.jpg","alt":"Black rhino in the grassland of Nairobi National Park"}]'::jsonb,'Spot lions, rhinos and giraffes against the city skyline — just 20 minutes from downtown Nairobi.',array['Rhinos & lions','Skyline views','Ideal for layovers'],'[{"day":"6:30am","title":"Hotel pick-up","description":"Collected from your hotel or JKIA."},{"day":"7:00am","title":"Game drive","description":"Four hours exploring the park''s plains and forest."},{"day":"11:30am","title":"Drop-off","description":"Return to your hotel or the airport."}]'::jsonb,d_inc,d_exc,d_faq,true,6),
('hells-gate-lake-naivasha-day-trip','day-trip','Hell''s Gate & Lake Naivasha','naivasha',1,10,'Full day · 10 hrs',120,1,'Nairobi hotel','1 – 7 guests','tours/hells-gate-lake-naivasha-day-trip/1-cover.jpg','Cyclists riding past Fischer''s Tower in Hell''s Gate','[{"src":"tours/hells-gate-lake-naivasha-day-trip/1-cover.jpg","alt":"Cyclists riding past Fischer''s Tower in Hell''s Gate"},{"src":"tours/hells-gate-lake-naivasha-day-trip/2.jpg","alt":"Hikers on a rocky trail in the gorge"},{"src":"tours/hells-gate-lake-naivasha-day-trip/3.jpg","alt":"Boat ride past hippos on Lake Naivasha"}]'::jsonb,'Cycle or hike through Hell''s Gate gorge, then take a boat among hippos on Lake Naivasha.',array['Cycling safari','Gorge hike','Hippo boat ride'],'[{"day":"7:00am","title":"Depart Nairobi","description":"Drive via the Rift Valley viewpoint."},{"day":"9:30am","title":"Hell''s Gate","description":"Cycle among zebras and hike the Ol Njorowa gorge."},{"day":"1:30pm","title":"Lake Naivasha","description":"Lunch, then a 1-hour boat ride to see hippos and fish eagles."},{"day":"5:30pm","title":"Return","description":"Drop-off at your hotel."}]'::jsonb,d_inc || array['Bicycle hire','Boat ride'],d_exc,d_faq,true,7),
('giraffe-centre-karen-blixen-day-trip','day-trip','Giraffe Centre & Karen Blixen Museum','nairobi',1,5,'Half day · 5 hrs',85,1,'Nairobi hotel','1 – 7 guests','tours/giraffe-centre-karen-blixen-day-trip/1-cover.jpg','Traveller feeding a Rothschild giraffe at the Giraffe Centre','[{"src":"tours/giraffe-centre-karen-blixen-day-trip/1-cover.jpg","alt":"Traveller feeding a Rothschild giraffe at the Giraffe Centre"},{"src":"tours/giraffe-centre-karen-blixen-day-trip/2.jpg","alt":"The Karen Blixen Museum farmhouse and gardens"}]'::jsonb,'Hand-feed endangered Rothschild giraffes, then step into the ''Out of Africa'' home of Karen Blixen.',array['Feed giraffes','Out of Africa house','Family friendly'],'[{"day":"8:30am","title":"Pick-up","description":"Collected from your Nairobi hotel."},{"day":"9:00am","title":"Giraffe Centre","description":"Feed and learn about Rothschild giraffes."},{"day":"11:00am","title":"Karen Blixen Museum","description":"Guided tour of the historic farmhouse."},{"day":"1:30pm","title":"Drop-off","description":"Return to your hotel."}]'::jsonb,d_inc,d_exc,d_faq,true,8),
('ol-pejeta-sheldrick-day-trip','day-trip','Ol Pejeta & Sheldrick Elephant Orphanage','laikipia',1,12,'Full day · 12 hrs',210,1,'Nairobi hotel','1 – 7 guests','tours/ol-pejeta-sheldrick-day-trip/1-cover.jpg','Baby elephants drinking milk at the elephant orphanage','[{"src":"tours/ol-pejeta-sheldrick-day-trip/1-cover.jpg","alt":"Baby elephants drinking milk at the elephant orphanage"},{"src":"tours/ol-pejeta-sheldrick-day-trip/2.jpg","alt":"Ranger standing beside a rhino at Ol Pejeta"}]'::jsonb,'Start at the Sheldrick Elephant Orphanage''s 11am feeding, then head north to meet the last northern white rhinos at Ol Pejeta.',array['Baby elephants','Northern white rhinos','Chimp sanctuary'],'[{"day":"6:00am","title":"Depart Nairobi","description":"Early pick-up from your hotel."},{"day":"11:00am","title":"Sheldrick feeding","description":"Watch orphaned baby elephants at feeding time."},{"day":"2:00pm","title":"Ol Pejeta","description":"Game drive and rhino enclosure visit."},{"day":"8:00pm","title":"Return","description":"Drop-off at your hotel."}]'::jsonb,d_inc,d_exc,d_faq,true,9),
('lake-nakuru-day-trip','day-trip','Lake Nakuru Rhino & Flamingo Day Trip','lake-nakuru',1,11,'Full day · 11 hrs',165,1,'Nairobi hotel','1 – 7 guests','tours/lake-nakuru-day-trip/1-cover.jpg','View over Lake Nakuru from Baboon Cliff','[{"src":"tours/lake-nakuru-day-trip/1-cover.jpg","alt":"View over Lake Nakuru from Baboon Cliff"},{"src":"tours/lake-nakuru-day-trip/2.jpg","alt":"Rothschild giraffe in the acacia woodland at Lake Nakuru"}]'::jsonb,'A full day game drive in Lake Nakuru National Park — one of the best places in Africa to see rhinos.',array['Rhinos','Flamingos','Baboon Cliff viewpoint'],'[{"day":"6:30am","title":"Depart Nairobi","description":"Drive through the Rift Valley."},{"day":"9:30am","title":"Game drive","description":"Full day in the park with picnic lunch."},{"day":"5:30pm","title":"Return","description":"Back to Nairobi by evening."}]'::jsonb,d_inc || array['Picnic lunch'],array['Tips & gratuities','Personal expenses'],d_faq,false,10),
('4-day-diani-beach-escape','beach','4-Day Diani Beach Escape','diani',4,null,'4 days / 3 nights',540,1,'Nairobi (SGR train) or Ukunda airstrip','1 – 12 guests','tours/4-day-diani-beach-escape/1-cover.jpg','White sand and turquoise water at Diani Beach','[{"src":"tours/4-day-diani-beach-escape/1-cover.jpg","alt":"White sand and turquoise water at Diani Beach"},{"src":"tours/4-day-diani-beach-escape/2.jpg","alt":"Traditional dhow sailing off the Diani coast"},{"src":"tours/4-day-diani-beach-escape/3.jpg","alt":"Colobus monkey in the coastal forest near Diani"}]'::jsonb,'White sand, warm Indian Ocean water and swaying palms. Relax on one of Africa''s best beaches with a dhow cruise and snorkelling trip included.',array['Award-winning beach','Dhow & snorkelling trip','Colobus monkey sanctuary'],'[{"day":"Day 1","title":"Nairobi → Diani","description":"Morning SGR train to Mombasa, transfer to your beachfront hotel and sunset on the sand."},{"day":"Day 2","title":"Kisite marine park","description":"Dhow trip to Kisite-Mpunguti Marine Park to snorkel coral reefs and spot dolphins, with a seafood lunch on Wasini Island."},{"day":"Day 3","title":"Free beach day","description":"Swim, relax or try optional kite-surfing and skydiving. Visit the Colobus Conservation centre."},{"day":"Day 4","title":"Diani → Nairobi","description":"Breakfast and transfer back to Mombasa for the train to Nairobi."}]'::jsonb,b_inc,b_exc,b_faq,true,11),
('5-day-watamu-marine-adventure','beach','5-Day Watamu Marine Adventure','watamu',5,null,'5 days / 4 nights',690,1,'Nairobi (SGR train) or Malindi airport','1 – 12 guests','tours/5-day-watamu-marine-adventure/1-cover.jpg','Sea turtle swimming over coral in Watamu Marine Park','[{"src":"tours/5-day-watamu-marine-adventure/1-cover.jpg","alt":"Sea turtle swimming over coral in Watamu Marine Park"},{"src":"tours/5-day-watamu-marine-adventure/2.jpg","alt":"Turquoise lagoon and sandbar at Watamu"},{"src":"tours/5-day-watamu-marine-adventure/3.jpg","alt":"Ancient coral ruins of Gede in the forest"}]'::jsonb,'Snorkel with sea turtles, walk the sandbars of Mida Creek and explore the ancient Gede Ruins on Kenya''s most beautiful marine coast.',array['Watamu Marine Park','Sea turtle rescue centre','Gede Ruins & Mida Creek'],'[{"day":"Day 1","title":"Nairobi → Watamu","description":"Travel to the coast and settle into your beach hotel."},{"day":"Day 2","title":"Marine park","description":"Glass-bottom boat and snorkelling in Watamu Marine National Park, then a visit to the Local Ocean turtle centre."},{"day":"Day 3","title":"Gede & Mida Creek","description":"Explore the 13th-century Gede Ruins and a sunset canoe ride through the mangroves of Mida Creek."},{"day":"Day 4","title":"Beach day","description":"A free day to swim, relax or try deep-sea fishing."},{"day":"Day 5","title":"Watamu → Nairobi","description":"Transfer back for your return journey."}]'::jsonb,b_inc,b_exc,b_faq,true,12),
('4-day-lamu-island-heritage','beach','4-Day Lamu Island Heritage','lamu',4,null,'4 days / 3 nights',780,1,'Wilson Airport, Nairobi (flight)','1 – 10 guests','tours/4-day-lamu-island-heritage/1-cover.jpg','Dhows with white sails in Lamu harbour','[{"src":"tours/4-day-lamu-island-heritage/1-cover.jpg","alt":"Dhows with white sails in Lamu harbour"},{"src":"tours/4-day-lamu-island-heritage/2.jpg","alt":"Narrow Swahili street in Lamu Old Town"},{"src":"tours/4-day-lamu-island-heritage/3.jpg","alt":"Empty white beach at Shela, Lamu"}]'::jsonb,'Step back in time on a UNESCO World Heritage island with no cars — only donkeys, dhows and carved Swahili doors.',array['Lamu Old Town (UNESCO)','Sunset dhow cruise','Shela beach'],'[{"day":"Day 1","title":"Fly to Lamu","description":"Morning flight from Wilson Airport, boat transfer to your guesthouse."},{"day":"Day 2","title":"Old Town walk","description":"Guided walk through Lamu Old Town, the fort and museum, then a sunset dhow cruise."},{"day":"Day 3","title":"Shela & islands","description":"Beach time at Shela and an optional trip to Manda Island."},{"day":"Day 4","title":"Fly back","description":"Return flight to Nairobi."}]'::jsonb,array['Return flights Nairobi – Lamu','Boat transfers','Guesthouse accommodation','Daily breakfast & dinner','Guided Old Town walk & dhow cruise'],b_exc,b_faq,true,13),
('3-day-malindi-coast-getaway','beach','3-Day Malindi Coast Getaway','malindi',3,null,'3 days / 2 nights',420,1,'Nairobi (SGR train) or Malindi airport','1 – 12 guests','tours/3-day-malindi-coast-getaway/1-cover.jpg','Vasco da Gama pillar on the Malindi shore','[{"src":"tours/3-day-malindi-coast-getaway/1-cover.jpg","alt":"Vasco da Gama pillar on the Malindi shore"},{"src":"tours/3-day-malindi-coast-getaway/2.jpg","alt":"Malindi beach at sunrise with fishing boats"},{"src":"tours/3-day-malindi-coast-getaway/3.jpg","alt":"Snorkeller over coral reef in Malindi Marine Park"}]'::jsonb,'A short, easy coastal break with history, coral reefs and long golden beaches — ideal after a safari.',array['Vasco da Gama pillar','Malindi Marine Park','Marafa ''Hell''s Kitchen'''],'[{"day":"Day 1","title":"Nairobi → Malindi","description":"Travel to the coast, afternoon walk to the Vasco da Gama pillar."},{"day":"Day 2","title":"Marine park","description":"Morning snorkelling in Malindi Marine Park; sunset at the Marafa Depression."},{"day":"Day 3","title":"Malindi → Nairobi","description":"Relaxed breakfast and return journey."}]'::jsonb,b_inc,b_exc,b_faq,true,14),
('hells-gate-team-building-day','corporate','Hell''s Gate Team-Building Day','naivasha',1,10,'Full day · 10 hrs',95,10,'Your Nairobi office','10 – 200 guests','tours/hells-gate-team-building-day/1-cover.jpg','Team cycling together through Hell''s Gate gorge','[{"src":"tours/hells-gate-team-building-day/1-cover.jpg","alt":"Team cycling together through Hell''s Gate gorge"},{"src":"tours/hells-gate-team-building-day/2.jpg","alt":"Colleagues sharing lunch at a lakeside camp in Naivasha"}]'::jsonb,'Get your team out of the office: cycling past zebras, a guided gorge hike and facilitated team challenges, with lunch by the lake.',array['Facilitated team challenges','Cycling & gorge hike','Lakeside lunch'],'[{"day":"7:00am","title":"Depart Nairobi","description":"Coach pick-up from your office."},{"day":"9:30am","title":"Hell''s Gate","description":"Cycling safari and guided gorge hike."},{"day":"1:00pm","title":"Lunch & challenges","description":"Lakeside lunch followed by facilitated team-building games."},{"day":"6:00pm","title":"Return","description":"Drop-off back at your office."}]'::jsonb,c_inc || array['Bikes & helmets','Lunch'],c_exc,c_faq,true,15),
('2-day-naivasha-leadership-retreat','corporate','2-Day Naivasha Leadership Retreat','naivasha',2,null,'2 days / 1 night',320,10,'Your Nairobi office','10 – 80 guests','tours/2-day-naivasha-leadership-retreat/1-cover.jpg','Outdoor meeting under acacia trees by Lake Naivasha','[{"src":"tours/2-day-naivasha-leadership-retreat/1-cover.jpg","alt":"Outdoor meeting under acacia trees by Lake Naivasha"},{"src":"tours/2-day-naivasha-leadership-retreat/2.jpg","alt":"Team on a boat ride among hippos on Lake Naivasha"}]'::jsonb,'Strategy sessions by the lake, a boat safari and an evening by the campfire — a retreat that leaves your leaders energised.',array['Conference room by the lake','Boat safari','Campfire dinner'],'[{"day":"Day 1","title":"Nairobi → Naivasha","description":"Arrive for a morning strategy session, lunch, then a boat ride among hippos and an evening campfire dinner."},{"day":"Day 2","title":"Workshops & walk","description":"Morning workshop, a walking safari on Crescent Island and return to Nairobi."}]'::jsonb,c_inc || array['Conference room & equipment','Full-board lakeside lodge'],c_exc,c_faq,true,16),
('4-day-maasai-mara-incentive-safari','corporate','4-Day Maasai Mara Incentive Safari','maasai-mara',4,null,'4 days / 3 nights',1450,8,'Wilson Airport, Nairobi (flight)','8 – 60 guests','tours/4-day-maasai-mara-incentive-safari/1-cover.jpg','Private bush dinner set up under the stars in the Maasai Mara','[{"src":"tours/4-day-maasai-mara-incentive-safari/1-cover.jpg","alt":"Private bush dinner set up under the stars in the Maasai Mara"},{"src":"tours/4-day-maasai-mara-incentive-safari/2.jpg","alt":"Group of guests on a game drive watching elephants in the Mara"}]'::jsonb,'Reward your top performers with a fly-in Maasai Mara safari: luxury tented camp, private game drives and a bush dinner under the stars.',array['Fly-in luxury safari','Private bush dinner','Awards evening'],'[{"day":"Day 1","title":"Fly to the Mara","description":"Scheduled flight from Wilson Airport, welcome drinks and an afternoon game drive."},{"day":"Day 2","title":"Full day safari","description":"Game drives with a picnic lunch by the Mara River."},{"day":"Day 3","title":"Balloon & bush dinner","description":"Optional sunrise balloon safari, free afternoon and a private bush dinner and awards evening."},{"day":"Day 4","title":"Fly back","description":"Morning game drive and flight to Nairobi."}]'::jsonb,c_inc || array['Return flights Nairobi – Mara','Luxury tented camp, full board','Private bush dinner'],c_exc || array['Balloon safari'],c_faq,true,17)
insert into public.reviews (name,country,flag,rating,trip,quote,source,sort_order) values
('Emma Thompson','United Kingdom','🇬🇧',5,'3-Day Maasai Mara Classic','We saw a river crossing on day two — our guide Joseph knew exactly where to be. Honest pricing, a spotless Land Cruiser and the best trip of our lives.','TripAdvisor',0),
('Daniel Okafor','Nigeria','🇳🇬',5,'Hell''s Gate & Lake Naivasha','Booking with M-Pesa took two minutes. Cycling past zebras and then hippos on the lake — unforgettable day.','Google',1),
('Sophie & Marc Laurent','France','🇫🇷',5,'4-Day Amboseli & Tsavo Explorer','Elephants under Kilimanjaro at sunrise. They tailored everything around our photography — truly local experts.','TripAdvisor',2),
('Priya Raman','India','🇮🇳',5,'Giraffe Centre & Karen Blixen','Perfect half-day with the kids. Pick-up was on time and our guide was wonderful with our children.','Google',3),
('Jake Miller','United States','🇺🇸',5,'5-Day Mara & Lake Nakuru Combo','We saw all of the Big Five plus rhinos at Nakuru. Responsive on WhatsApp before and during the trip.','TripAdvisor',4),
