insert into public.articles (slug,title,excerpt,image,image_alt,read_time,published_on,body) values
('best-time-to-visit-maasai-mara','Best Time to Visit the Maasai Mara','Dry season, green season and migration months — how to pick the right time for your safari.','blog/best-time-to-visit-maasai-mara.jpg','Two lionesses lying in the grass','5 min read','2026-09-12','[{"heading":"Dry season (June – October)","text":"Short grass and fewer water sources concentrate wildlife, making game viewing excellent. July to October is peak Great Migration season with dramatic Mara River crossings."},{"heading":"Green season (November – May)","text":"Lush landscapes, newborn animals and fewer vehicles. Short rains in November and long rains in April–May bring lower rates — great value for flexible travellers."},{"heading":"Our tip","text":"For crossings, aim for August–September. For value and photography with dramatic skies, consider January–March."}]'::jsonb),
('what-to-pack-for-a-safari','What to Pack for a Safari','Neutral layers, the right binoculars and the one item every guest forgets.','blog/what-to-pack-for-a-safari.jpg','Safari packing essentials laid out: binoculars, hat, camera and khaki clothing','4 min read','2026-08-02','[{"heading":"Clothing","text":"Pack neutral colours (khaki, olive, beige), a warm fleece for early mornings, a wide-brim hat and comfortable closed shoes."},{"heading":"Gear","text":"Binoculars (8x42 are ideal), a camera with zoom lens, power bank, sunscreen and insect repellent. Soft-sided bags are best for vehicles and light aircraft."},{"heading":"The item everyone forgets","text":"A buff or scarf — dusty roads in the dry season make it your best friend on game drives."}]'::jsonb),
('great-migration-calendar','Great Migration Calendar','Month by month: where the herds are and when to see the river crossings.','blog/great-migration-calendar.jpg','Wildebeest herds streaming across the plains during the Great Migration','6 min read','2026-07-18','[{"heading":"January – March","text":"Calving season in the southern Serengeti (Tanzania). Over 8,000 calves are born daily in February."},{"heading":"April – June","text":"Herds move north and west through the Serengeti''s central and western corridors."},{"heading":"July – October","text":"The herds arrive in the Maasai Mara. Mara River crossings peak in August and September."},{"heading":"November – December","text":"The herds return south to the Serengeti with the short rains."}]'::jsonb)
